(7761894, 1285771, 100831, '<td valign="top">The light is stunning. This got one of my top votes.</td>', 'The light is stunning. This got one of my top votes.', '2024-01-08 10:35:01.000000', NULL, 0),
(7761895, 1285886, 100831, '<td valign="top">One of my two 8s in the challenge. Love that light.</td>', 'One of my two 8s in the challenge. Love that light.', '2024-01-08 10:36:36.000000', NULL, 0),
(7761896, 1285936, 100831, '<td valign="top">Dreamy.</td>', 'Dreamy.', '2024-01-08 10:39:16.000000', NULL, 0),
(7761899, 1285928, 173844, '<td valign="top">This is one of my favorites.  I love the crisp detail and contrast.  The scene thereby becomes a momentary insight, unbidden, powerful.</td>', 'This is one of my favorites.  I love the crisp detail and contrast.  The scene thereby becomes a momentary insight, unbidden, powerful.', '2024-01-08 10:58:08.000000', NULL, 0),
(7761900, 1285771, 129512, '<td valign="top">Knowing the window and scene are staged make this (and your subsequent portfolio with Cleopatra and Moriarty) all that more impressive. Love the full scene crop and overall composition.</td>', 'Knowing the window and scene are staged make this (and your subsequent portfolio with Cleopatra and Moriarty) all that more impressive. Love the full scene crop and overall composition.', '2024-01-08 11:08:51.000000', NULL, 0),
(7761901, 1285932, 173844, '<td valign="top">Lovely still life.  Very nice how the roundness of the pomegranate is echoed by the bowl.  In the spirit of friendly criticism, here are two subjective comments.  As MaryO wrote, the echoing of the pomegranate red in the greenery lends the image a comfortable balance.  However, the two shiny, bright clusters on the left seem out of character with the subdued mood of the background.  Also, the metal spoon feels extraneous, not adding much to the photo.  To reiterate, subjective.  Perhaps you felt that something was needed for bottom weight, I don''t know.</td>', 'Lovely still life.  Very nice how the roundness of the pomegranate is echoed by the bowl.  In the spirit of friendly criticism, here are two subjective comments.  As MaryO wrote, the echoing of the pomegranate red in the greenery lends the image a comfortable balance.  However, the two shiny, bright clusters on the left seem out of character with the subdued mood of the background.  Also, the metal spoon feels extraneous, not adding much to the photo.  To reiterate, subjective.  Perhaps you felt that something was needed for bottom weight, I don''t know.', '2024-01-08 11:20:20.000000', NULL, 0),
(7761902, 1285901, 173844, '<td valign="top">Underappreciated, in my opinion.  One of my favorites.</td>', 'Underappreciated, in my opinion.  One of my favorites.', '2024-01-08 11:23:17.000000', NULL, 0),
(7761918, 1285771, 67145, '<td valign="top">once again the cat whisperer creates another amazing image .. <br/>many congrats Wendy for this gorgeous portrait .. and of course the ribbon .. :)</td>', 'once again the cat whisperer creates another amazing image .. many congrats Wendy for this gorgeous portrait .. and of course the ribbon .. :)', '2024-01-08 15:16:24.000000', NULL, 0),
(7761949, 1285810, 30214, '<td valign="top">Wonderful portrait, Eli!</td>', 'Wonderful portrait, Eli!', '2024-01-09 16:47:43.000000', NULL, 0),
